query.base:
TS metrics-gcp.cloudstorage.otel-default
// Scope to Cloud Storage; this data stream carries every GCP service the receiver collects.
| WHERE resource.attributes.gcp.resource_type == "gcs_bucket"
    AND `metrics.storage.googleapis.com/api/request_count` IS NOT NULL
// Client-fault codes other than the authorization pair, which has its own, traffic-normalised rule
// (gcp_cloudstorage_otel-authorization-failure-surge). Anything not listed here is handled by
// gcp_cloudstorage_otel-service-fault-errors, so the two rules together cover every possible code.
| WHERE attributes.response_code IN (
      "NOT_FOUND", "INVALID_ARGUMENT", "FAILED_PRECONDITION",
      "OUT_OF_RANGE", "ALREADY_EXISTS", "CANCELLED")
// The rule compares the last 2h ("recent") with two baselines: the 22h before them, which keeps a
// normal diurnal peak from reading as a step change, and the same time of day on each of the
// previous 7 days, which keeps a daily or weekly batch from alerting again once it has run before.
// The same-time window runs from 3h before to 1h after this time of day, so a batch that starts a
// little earlier or later, or moves an hour with daylight saving time, still matches.
// same_time_day is k when the sample falls in that window on the k-th previous day, otherwise 0;
// the rule's 171h window covers day 7.
| EVAL minutes_ago   = DATE_DIFF("minutes", @timestamp, NOW()),
       same_time_day = CASE((minutes_ago + 60) % 1440 < 240, (minutes_ago + 60) / 1440, 0)
// request_count is a ~60s delta counter stored as a gauge. SUM_OVER_TIME totals each series and SUM
// adds the series together: the collector can split one bucket's metric across several series
// (_metric_names_hash is a dimension), and each sample is still counted once. Never RATE() it.
// Each day gets its own filtered aggregation: grouping TS results BY a computed day does not split
// the per-series totals.
| STATS recent_faults    = SUM(SUM_OVER_TIME(`metrics.storage.googleapis.com/api/request_count`)) WHERE @timestamp >= NOW() - 2 hours,
        baseline_faults  = SUM(SUM_OVER_TIME(`metrics.storage.googleapis.com/api/request_count`)) WHERE @timestamp >= NOW() - 24 hours AND @timestamp < NOW() - 2 hours,
        day_1            = SUM(SUM_OVER_TIME(`metrics.storage.googleapis.com/api/request_count`)) WHERE same_time_day == 1,
        day_2            = SUM(SUM_OVER_TIME(`metrics.storage.googleapis.com/api/request_count`)) WHERE same_time_day == 2,
        day_3            = SUM(SUM_OVER_TIME(`metrics.storage.googleapis.com/api/request_count`)) WHERE same_time_day == 3,
        day_4            = SUM(SUM_OVER_TIME(`metrics.storage.googleapis.com/api/request_count`)) WHERE same_time_day == 4,
        day_5            = SUM(SUM_OVER_TIME(`metrics.storage.googleapis.com/api/request_count`)) WHERE same_time_day == 5,
        day_6            = SUM(SUM_OVER_TIME(`metrics.storage.googleapis.com/api/request_count`)) WHERE same_time_day == 6,
        day_7            = SUM(SUM_OVER_TIME(`metrics.storage.googleapis.com/api/request_count`)) WHERE same_time_day == 7,
        affected_methods = VALUES(attributes.method) WHERE @timestamp >= NOW() - 2 hours
    BY resource.attributes.bucket_name, attributes.response_code
| EVAL peak_same_time_faults = GREATEST(COALESCE(day_1, 0), COALESCE(day_2, 0), COALESCE(day_3, 0), COALESCE(day_4, 0),
                                        COALESCE(day_5, 0), COALESCE(day_6, 0), COALESCE(day_7, 0))
| DROP day_1, day_2, day_3, day_4, day_5, day_6, day_7
| EVAL recent_faults = COALESCE(recent_faults, 0), baseline_faults = COALESCE(baseline_faults, 0)

breach.segment:
// Absolute floor first, so a code that was previously absent cannot page on a handful of requests.
WHERE recent_faults >= 50
// Cast before dividing: request_count is a long and `a / b` would be integer division.
// 2.0, 22.0 and 4.0 are the slice widths in hours — keep them in sync with the slices above and
// timeWindowSize.
| EVAL recent_faults_per_hour         = ROUND(recent_faults::DOUBLE / 2.0, 2),
       baseline_faults_per_hour       = ROUND(baseline_faults::DOUBLE / 22.0, 2),
       peak_same_time_faults_per_hour = ROUND(peak_same_time_faults::DOUBLE / 4.0, 2)
// Step-change test on the unrounded hourly rates, against the higher of the two baselines, so the
// recent rate must be a step change on both the preceding hours and the busiest of the previous 7
// days at this time. A code with no faults in either baseline is compared against 1 fault/hour
// instead, so the ratio stays finite; the volume floor above already makes such a code significant.
| EVAL reference_faults_per_hour = GREATEST(baseline_faults::DOUBLE / 22.0, peak_same_time_faults::DOUBLE / 4.0)
| EVAL step_change_factor = ROUND((recent_faults::DOUBLE / 2.0)
      / CASE(reference_faults_per_hour > 0, reference_faults_per_hour, 1.0), 2)
| WHERE step_change_factor >= 3.0
| EVAL alert_key = CONCAT(resource.attributes.bucket_name, " / ", attributes.response_code)
| SORT step_change_factor DESC
| LIMIT 50
